// Função para gerar uma chave de acesso aleatória
function generateAccessKey() {
return [...Array(50)].map(() => Math.random().toString(36)[2]).join('');
}

// Função para hash da chave de acesso
async function hashAccessKey(accessKey) {
const encoder = new TextEncoder();
const data = encoder.encode(accessKey);
const hashBuffer = await crypto.subtle.digest('SHA-256', data);
const hashArray = Array.from(new Uint8Array(hashBuffer));
return hashArray.map(b => b.toString(16).padStart(2, '0')).join('');
}

// Função para redirecionar (melhora a organização)
function redirectTo(url) {
window.location.href = url;
}

async function handleRegister() {
const username = document.getElementById('newUsername').value;
const password = document.getElementById('newPassword').value;
const accessKey = generateAccessKey();

try {
const hashedAccessKey = await hashAccessKey(accessKey);
const response = await fetch('register.php', {
method: 'POST',
headers: { 'Content-Type': 'application/json' },
body: JSON.stringify({ username, password, accessKey }),
});


const result = await response.json();

if (result.success) {
  localStorage.setItem('hashedAccessKey', hashedAccessKey);
  alert('Conta criada e chave de acesso gerada com sucesso!');
  showLoginForm(); 
} else {
  alert(result.message);
}
} catch (error) {
alert("Erro ao registrar: " + error.message);
}
}

